from pathlib import Path
import shutil, json, xml.etree.ElementTree as ET
root=Path('outputs'); kit=root/'consent-waypoint-brand-kit'
shutil.copytree(root/'brand-assets',kit/'brand-assets',dirs_exist_ok=True)
for name in ['brand-tokens.css','brand-tokens.json','contrast-checks.json']:
 if (root/name).exists():shutil.copy2(root/name,kit/name)
# Original editable artwork uses the same bounded evidence motif in five different mechanisms.
def svg(name,body,bg='#F6F3EC',title='Original Consent Waypoint illustration'):
 out=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 500" role="img"><title>{title}</title><defs><filter id="shadow"><feDropShadow dx="0" dy="12" stdDeviation="14" flood-color="#202522" flood-opacity=".12"/></filter><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0L10 5L0 10" fill="#5A625D"/></marker></defs><rect width="800" height="500" fill="{bg}"/><g font-family="Arial,sans-serif" fill="#202522">{body}</g></svg>'''
 (kit/'visuals'/f'{name}.svg').write_text(out)
def box(x,y,w,h,fill='#FFFEFA',rx=12):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{rx}" fill="{fill}" stroke="#8B948D"/>'
def txt(x,y,t,size=18,fill='#202522'):return f'<text x="{x}" y="{y}" font-size="{size}" fill="{fill}">{t}</text>'
def line(x,y,X,Y,dash=False):return f'<path d="M{x} {y}L{X} {Y}" stroke="#5A625D" stroke-width="2" fill="none" marker-end="url(#arrow)"'+(' stroke-dasharray="6 6"' if dash else '')+'/>'
