ns='{http://www.w3.org/2000/svg}'; tree=ET.parse(kit/'brand-assets/icons.svg'); (kit/'icons').mkdir(exist_ok=True)
for sym in tree.getroot():
 e=ET.Element(ns+'svg',{'viewBox':sym.attrib['viewBox'],'fill':'none'});e.extend(list(sym)); ET.ElementTree(e).write(kit/'icons'/f"{sym.attrib['id']}.svg",encoding='unicode')
