def image(name,alt):return f'<img src="visuals/{name}.svg" alt="{alt}" loading="lazy" width="800" height="500">'
def figure(name,alt):return f'<figure class="diagram">{image(name,alt)}<figcaption>{alt} · <a href="visuals/{name}.svg" download>Editable SVG ↓</a></figcaption></figure>'
def section(id,num,title,intro,body,cls=''):return f'<section id="{id}" class="{cls}"><div class="wrap"><p class="eyebrow">{num} / Evidence in Motion</p><h2>{title}</h2><p class="intro">{intro}</p>{body}</div></section>'
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Consent Waypoint — Evidence in Motion. Complete interactive brand kit with original assets, components and synthetic product specimens."><title>Consent Waypoint — Complete brand kit</title><link rel="icon" href="brand-assets/favicon.svg"><link rel="stylesheet" href="brand-tokens.css"><link rel="stylesheet" href="kit.css"></head><body><a class="skip" href="#main">Skip to brand kit</a><header class="topbar"><div class="wrap"><a href="#main" aria-label="Consent Waypoint brand kit"><img class="logo" src="brand-assets/logo-primary.svg" alt="Consent Waypoint"></a><nav class="nav" aria-label="Brand kit"><a href="#identity">Identity</a><a href="#environments">Environments</a><a href="#components">Components</a><a href="#workbench">Workbench</a><a class="button" href="../Consent-Waypoint-brand-kit.zip" download>Download kit ↓</a></nav></div></header><main id="main"><div class="hero"><div class="wrap"><div class="hero-grid"><div><p class="eyebrow">Consent Waypoint / Brand system 2.0</p><h1>The source.<br>The permission.<br>The next step.</h1><p class="lead">Evidence in Motion. A complete visual language for keeping rights, context and human review together.</p><div class="actions"><a class="button" href="#environments">Explore the system <span class="arr">→</span></a><a class="button secondary" href="CONSENT_WAYPOINT_BRAND_IDENTITY.md">Read the brand guide ↗</a></div><p class="meta small-top">Identity and interaction specimens.<br>Research-stage concept · Product examples are synthetic.</p></div><div class="art"><img src="visuals/folio-still.png" alt="Original material study: layered paper folios, lilac dividers and a coral waypoint" width="1024" height="1024"><div class="hero-note">01 / THE CLAUSE WINDOW<br>Frame the evidence. Keep its context.</div></div></div><nav class="chapter-nav" aria-label="All kit sections">'''
chapters=[('identity','01 Identity'),('palette','02 Palette'),('type','03 Typography'),('layout','04 Grid & space'),('depth','05 Depth'),('environments','06 Backgrounds'),('components','07 Cards'),('states','08 States'),('workbench','09 Dashboard'),('visuals','10 Diagrams & maps'),('flows','11 User flows'),('charts','12 Charts'),('icons','13 Icons'),('motion','14 Motion'),('commercial','15 Pricing & stats'),('testimonials','16 Testimonials'),('forms','17 Forms'),('downloads','18 Handoff')]
html+=''.join(f'<a href="#{i}">{n}</a>' for i,n in chapters)+'</nav></div></div>'
html+=section('identity','01','A frame for the evidence.','Two opposing brackets define a source boundary. A single coral waypoint marks the question to inspect.',f'''<div class="split"><div><div class="panel logo-tile"><img src="brand-assets/logo-primary.svg" alt="Primary logo"></div><p class="meta small-top">Primary / warm paper · <a href="brand-assets/logo-primary.svg" download>SVG ↓</a></p></div><div><div class="panel dark logo-tile"><img src="brand-assets/logo-reverse.svg" alt="Reverse logo"></div><p class="meta small-top">Reverse / ink · <a href="brand-assets/logo-reverse.svg" download>SVG ↓</a></p></div></div><div class="three big-top"><div class="rail"><h3>Clear space</h3><p class="small-top">Keep one waypoint diameter clear on all sides. Never stretch or add a glow.</p></div><div class="rail"><h3>Small, legible marks</h3><div class="actions"><img src="brand-assets/favicon-32.png" alt="32px favicon" width="32" height="32"><img src="brand-assets/mark-primary.svg" alt="Primary mark" width="48" height="48"></div><p class="meta small-top">Favicon 16–48px · UI mark ≥20px</p></div><div class="rail"><h3>Production assets</h3><p class="small-top">Outlined wordmarks, editable lockup, monochrome, reverse, compact, PNG and ICO exports.</p><a href="brand-assets/logo-compact.svg" download>Compact lockup ↓</a></div></div>''','lilac')
html+=section('palette','02','Warmth with a precise signal.','Coral attracts attention. Decision colors carry their own meaning. Select a swatch to copy its value.','<div class="swatches" id="swatches"></div><div class="actions"><span class="pill allow">✓ Allow</span><span class="pill counsel">◷ Requires counsel</span><span class="pill deny">⊖ Deny</span></div><p class="meta small-top">Expression coral is decorative. Darker action coral supports button text. Fourteen specified contrast pairings are supplied; this is not a whole-site accessibility certification.</p>')
styles=[('Display','88 / 44 · 650 · 1.02',64,'Every use has context.'),('H1','64 / 40 · 650 · 1.08',48,'Begin with the source.'),('H2','52 / 32 · 650 · 1.12',38,'Keep the reason close.'),('H3','32 / 26 · 650 · 1.2',30,'Five distinct rights'),('H4','24 / 22 · 650 · 1.25',24,'Review the request'),('H5','20 / 20 · 650 · 1.3',20,'Approved source metadata'),('H6','16 / 16 · 700 · 1.4',16,'A visible next action'),('Body large','18 / 17 · 400 · 1.6',18,'Permission to read does not answer every question about use.'),('Body / UI','16 / 15 · 400–600 · 1.5',16,'Inspect the clause, destination and review status.'),('Label','13 / 13 · 650 · 1.4',13,'Destination · external model'),('Caption','12 / 12 · 400 · 1.5',12,'Illustrative content. Human review remains explicit.'),('Data','12 / 12 · Mono 400 · 1.6',12,'LIC-17 / §4.3 / policy v1.0')]
html+=section('type','03','A voice that makes detail readable.','Manrope for the conversation. IBM Plex Mono for the record. Local fonts and original license notices are included.',''.join(f'<div class="type-row"><div><b>{n}</b><small>{d}<br>desktop / mobile px</small></div><div class="type-sample" style="font-size:clamp({min(z,32)}px,{z/14.4}vw,{z}px);'+('font-family:var(--cw-font-data)' if n=='Data' else '')+f'">{t}</div></div>' for n,d,z,t in styles),'sheet')
html+=section('layout','04','Space is part of the explanation.','A consistent underlying grid lets the surface, media and composition change between chapters.','''<div class="split"><div><div class="toggle-group" aria-label="Grid schematic"><button data-cols="12" aria-pressed="true">Desktop / 12</button><button data-cols="8" aria-pressed="false">Tablet / 8</button><button data-cols="4" aria-pressed="false">Mobile / 4</button></div><div class="grid-preview" id="gridPreview"></div><p id="gridNote" class="meta small-top">Desktop: 64px margins at 1440px · 24px gaps · 1312px maximum content.</p></div><div class="panel"><h3>Layout contracts</h3><div class="table-wrap"><table><caption>Grid values at the named breakpoint</caption><thead><tr><th>Width</th><th>Columns</th><th>Margin</th><th>Gap</th></tr></thead><tbody><tr><td>≥1200</td><td>12</td><td>64px min</td><td>24px</td></tr><tr><td>768–1199</td><td>8</td><td>32px</td><td>24px</td></tr><tr><td>≤767</td><td>4</td><td>20px</td><td>16px</td></tr></tbody></table></div><p class="meta">Reading ≤720px · Forms ≤640px · At 390px: 350px content. Wide diagrams have text equivalents.</p></div></div><div class="spacing" id="spacing"></div><div class="three big-top"><div class="rail"><b>24 / 20px</b><p>Card padding, desktop / mobile.</p></div><div class="rail"><b>40–48px</b><p>Copy to its supporting visual.</p></div><div class="rail"><b>96–128 / 56–72px</b><p>Chapter padding, desktop / mobile.</p></div></div>''')
html+=section('depth','05','Depth follows responsibility.','Tables stay flat. Evidence can lift from its source. Overlays sit above the active workbench.','<div class="four">'+''.join(f'<div class="panel depth" style="box-shadow:{v}"><h3>{n}</h3><code>{v}</code></div>' for n,v in [('Flat','none'),('Paper','0 8px 24px #20252214'),('Evidence','0 20px 64px #2025221f'),('Overlay','0 24px 80px #2025222e')])+'</div><p class="meta big-top">Radii: label 4px / control 8px / evidence 12px / media 16px / scene 24px.<br>Layers: base 0 / diagram 1 / evidence 10 / header 40 / menu 50 / modal 80.</p>','sheet')
html+=section('environments','06','Eight environments. Eight different jobs.','Select a background to see where it belongs. The typography and evidence frame keep the family connected.','''<div class="toggle-group" id="environmentControls" aria-label="Background environment"></div><div id="environment" class="environment env-paper"><div class="scene-copy"><p class="eyebrow" id="envCode">E1 / PAPER FIELD</p><h3 id="envTitle">Introduce the source.</h3><p id="envCopy" class="small-top">Home, company and workshop introductions. Quiet space for a strong proposition.</p></div></div><div id="environmentGallery" class="environments"></div>''')
html+=section('components','07','Each card has a different kind of evidence.','Illustrations, image treatments, structured records and a second face. Interactions reveal context without moving the reading target.',f'''<div class="three cards"><article class="panel media-card"><div class="media"><img src="visuals/folio-still.png" alt="Original paper folio material image" loading="lazy"></div><div class="body"><p class="eyebrow">Image feature / Rights Desk</p><h3>Start at the clause.</h3><p>Original material artwork introduces the source before the readable record.</p><button class="button text" data-note="Image card: 8:5 crop, 24px content padding, 2px lift and 1.025× media reveal.">Inspect treatment <span class="arr">→</span></button></div></article><article class="panel media-card"><div class="media">{image('decision-route','Request and three labeled outcomes')}</div><div class="body"><p class="eyebrow">Illustrated mechanism / Review</p><h3>Change the destination.</h3><p>A branch diagram makes the difference between permission and review visible.</p><button class="button text" data-note="Diagram card: labeled ports, semantic states, no customer or integration claims.">Inspect diagram <span class="arr">→</span></button></div></article><article class="panel"><p class="eyebrow">Operational record</p><h3>LIC-17 / Atlas Reference</h3><p><span class="pill counsel">◷ Requires counsel</span></p><p>External inference · source §4.3<br>Owner: Mira Lane (fictional)<br>Next action: review destination</p><p class="meta">DEMO — SYNTHETIC DATA<br>Sample date: 8 October 2026</p><a class="button secondary small-top" href="#workbench">Inspect record →</a></article></div><div class="split big-top"><div><p class="eyebrow">Evidence flip / Explicit activation</p><h3>Turn to the citation.</h3><p class="small-top">Hover hints at depth. Tap, Enter or Space on the control turns the card. Essential status stays outside both faces.</p><p class="small-top"><span class="pill counsel">Requires counsel · Output: None</span></p><button class="button small-top" id="flipControl" aria-expanded="false" aria-controls="flipCard">Inspect evidence</button></div><div class="flip-shell"><div class="flip" id="flipCard"><div class="face" id="flipFront"><p class="eyebrow">Summary / LIC-17</p><h3>External inference<br>needs review.</h3><p>DEMO — SYNTHETIC DATA</p></div><div class="face back" id="flipBack" inert aria-hidden="true"><p class="eyebrow">Fictional clause / §4.3</p><h3>External inference requires prior written permission.</h3><p class="meta">Illustrative wording, not an approved legal opinion. Review state: unresolved.</p></div></div></div></div>''','sage')
html+=section('states','08','The small details are the system.','Hover, keyboard focus and press are distinct. Loading and empty states explain what is happening.','''<div class="state-grid"><div class="state-card"><button class="button" data-note="Primary action activated locally.">Default →</button><p>48px target / 8px radius</p></div><div class="state-card"><button class="button hover-demo" data-note="Hover specimen: action fill darkens; arrow travels 4px.">Hover specimen →</button><p>180ms fill + arrow</p></div><div class="state-card"><button class="button secondary focus-demo" data-note="Focus specimen: 3px focus ring, 3px offset.">Focus specimen</button><p>Visible ring / no layout shift</p></div><div class="state-card"><button class="button press-demo" data-note="Pressed specimen: darker fill and 1px offset.">Pressed specimen</button><p>1px press / stable label</p></div><div class="state-card"><button class="button selected-demo" aria-pressed="true" id="selectedButton">Selected</button><p>Toggle changes aria-pressed</p></div><div class="state-card"><button class="button" disabled>Unavailable</button><p>Requires an approved source</p></div><div class="state-card"><button class="button" disabled>Saving specimen…</button><p>Static loading-state sample</p></div><div class="state-card"><button class="button text" data-note="Text action: underline and arrow behavior, no hidden content.">Text action →</button><p>Quiet secondary emphasis</p></div></div><div class="three big-top"><div class="panel"><span class="pill allow">✓ Local preview complete</span><p>Nothing was sent.</p></div><div class="panel"><span class="pill counsel">◷ Empty state</span><p>No approved source metadata yet.</p></div><div class="panel"><div class="field"><label for="errorExample">Work email / error specimen</label><input id="errorExample" value="example" aria-invalid="true" aria-describedby="errorHelp"><small class="error" id="errorHelp">Enter a complete email address.</small></div></div></div>''')
html+=section('workbench','09','A workbench around one concrete decision.','Choose a source, then change the requested use and destination. The result stays tied to a fictional clause and a visible next action.','''<div class="workbench"><div class="notice">DEMO — SYNTHETIC DATA · CONCEPT PREVIEW · No external calls or policy writes</div><div class="workbar"><div><h3>Rights review desk</h3><p class="meta">Fixed sample date / 08 Oct 2026</p></div><button class="button secondary" id="resetDemo">Reset demo</button></div><div class="worklayout"><aside class="queue" id="queue" aria-label="Fictional source records"></aside><div class="workmain"><p class="eyebrow" id="recordID">LIC-17</p><h3 id="recordName">Atlas Reference</h3><div class="form-grid"><div class="field"><label for="purpose">Requested use</label><select id="purpose"><option value="read">Read / internal research</option><option value="embedding">Embedding</option><option value="inference" selected>Model inference</option><option value="retention">Retain / 90 days</option><option value="redistribution">Redistribution</option></select></div><div class="field"><label for="destination">Destination</label><select id="destination"><option value="internal">Internal approved boundary</option><option value="external" selected>External model provider</option></select></div></div><p class="meta">Separate synthetic access check: read entitlement present. Use permission is evaluated below.</p><div class="table-wrap"><table><caption>LIC-17 illustrative rights matrix</caption><thead><tr><th>Right</th><th>Rule</th></tr></thead><tbody><tr><td>Read</td><td>Internal research allowed</td></tr><tr><td>Embed</td><td>Approved internal index only</td></tr><tr><td>External inference</td><td>Requires counsel</td></tr><tr><td>Retain</td><td>Duration requires explicit review</td></tr><tr><td>Redistribute</td><td>Denied</td></tr></tbody></table></div><p class="meta small-top">Index and 90-day controls are synthetic assumptions. Selecting a request never executes content.</p></div><aside class="evidence"><p class="eyebrow">Decision evidence</p><div id="decision" aria-live="polite"></div><h4>Source citation</h4><p id="clauseText"></p><h4>Review & next action</h4><p id="nextAction"></p><h4>Receipt</h4><pre id="receipt"></pre></aside></div></div><details class="small-top"><summary>Data dictionary and limits</summary><p class="small-top">Source ID identifies a fictional document; request outcome is separate from review status and access entitlement. Allow is permission in this fixture context, not execution. Requires counsel pauses the request. Deny blocks it. All outputs here are None. Missing conditions never imply permission. Reset restores in-memory defaults.</p></details>''','ink')
html+=section('visuals','10','Diagram the relationship.<br>Map the boundary.','Original editable visuals show policy context, evidence references and source destinations. Location is not part of the product story.',f'''<div class="split">{figure('receipt-chain','Decision evidence links source, version and receipt; unresolved requests have no output lineage')}{figure('destination-map','Conceptual destination map: internal read and external review, not geographic coverage')}</div><div class="three cards big-top">{figure('rights-folio','Rights Desk / source folio')}{figure('deadline-calendar','Rights Signal / sample deadline')}{figure('report-ledger','Rights Report / synthetic statement')}</div><p class="meta big-top">Ports attach to node edges. Solid = represented relationship. Dashed = proposed boundary. Labels remain readable. All product illustrations use synthetic data.</p>''')
html+=section('flows','11','People own the next step.','The product flow follows a request. The buyer flow follows the agreement to evaluate one source family.',f'''<div class="split">{figure('reviewer-flow','Fictional owner → counsel → engineer → paused review → receipt')}<div><h3>Workshop journey</h3><div class="journey small-top" id="journey"><button aria-pressed="true" data-step="0"><b>01 / Understand</b>Why rights?</button><button aria-pressed="false" data-step="1"><b>02 / Inspect</b>Synthetic evidence</button><button aria-pressed="false" data-step="2"><b>03 / Qualify</b>Owner + counsel</button><button aria-pressed="false" data-step="3"><b>04 / Scope</b>Funded pilot</button></div><p class="small-top" id="journeyCopy" aria-live="polite">Explain the distinction between access entitlement and permitted use.</p><p class="meta small-top">A request is not a booking. A booked workshop is not a funded pilot.</p></div></div>''','sheet')
html+=section('charts','12','Numbers with a source you can inspect.','Ten fixed synthetic request events demonstrate reporting. Select a bar to filter its records. These are evaluations, not usage or performance results.','''<div class="split"><div><div class="notice">DEMO — SYNTHETIC DATA · 10 simulated requests · Sample date 08 Oct 2026</div><div class="chart"><button class="bar" data-filter="allow" aria-pressed="false" aria-label="Filter four Allow events"><b>4</b><i style="height:160px"></i></button><button class="bar" data-filter="counsel" aria-pressed="false" aria-label="Filter three Requires counsel events"><b>3</b><i style="height:120px"></i></button><button class="bar" data-filter="deny" aria-pressed="false" aria-label="Filter three Deny events"><b>3</b><i style="height:120px"></i></button></div><div class="chart-labels"><span>Allow</span><span>Requires counsel</span><span>Deny</span></div><button class="button secondary small-top" id="clearFilter">Show all 10 requests</button></div><div class="table-wrap"><table><caption id="eventCaption" aria-live="polite">All 10 synthetic request events</caption><thead><tr><th>Event</th><th>Source</th><th>Decision</th></tr></thead><tbody id="eventRows"></tbody></table></div></div><div class="split big-top"><div class="panel"><h3>Source × use matrix</h3><p class="meta">Synthetic example · labeled cells provide the color equivalent</p><div class="heatmap"><span>Source</span><span>Read</span><span>External AI</span><span>Redistribute</span><span>LIC-17</span><span class="allow">Allow</span><span class="counsel">Counsel</span><span class="deny">Deny</span><span>LIC-22</span><span class="counsel">Counsel</span><span class="counsel">Counsel</span><span class="deny">Deny</span><span>LIC-31</span><span class="deny">Deny</span><span class="deny">Deny</span><span class="deny">Deny</span></div></div><div class="rail"><h3>Chart contract</h3><p class="small-top">Every chart names its unit, source, sample date and denominator. Counts reconcile with its table. Unknown stays unknown. Decision counts never become savings, customer traction or legal assurance.</p></div></div>''','sage')
html+=section('icons','13','A consistent set of small signals.','Twenty-six original SVG icons. 24px viewBox, 1.75px rounded strokes, 16 / 20 / 24 / 32px display sizes. Select an icon to download it.','<div class="icons" id="iconsGrid"></div><div class="split big-top"><div><h3>Company profile marks</h3><p class="small-top">Recognizable LinkedIn and Crunchbase icons are included as separate monochrome specimens. Profile links remain unconfigured.</p><div class="socials small-top"><button data-note="LinkedIn company profile is not configured. No external page was opened."><img src="social/linkedin.svg" alt="">LinkedIn<small>Profile pending</small></button><button data-note="Crunchbase company profile is not configured. No external page was opened."><img src="social/crunchbase.svg" alt="">Crunchbase<small>Profile pending</small></button></div></div><div class="panel"><h3>Asset provenance</h3><p>LinkedIn graphic: Bootstrap Icons, MIT. Crunchbase graphic: Simple Icons, CC0. Brand marks remain trademarks; library licenses do not imply brand approval.</p><p class="meta">Preview specimens. Confirm applicable trademark usage before publication. No invented company URLs.</p></div></div>')
html+=section('motion','14','One source, moving through the story.','A bounded folio shifts from intake to inspection to decision evidence. The scene is a working motion specimen for the future scroll story.','''<div class="split"><div><div class="toggle-group" aria-label="Motion storyboard"><button data-stage="1" aria-pressed="true">01 Source</button><button data-stage="2" aria-pressed="false">02 Inspect</button><button data-stage="3" aria-pressed="false">03 Receipt</button></div><p id="motionCopy" aria-live="polite">A stable source folio enters the scene; the claim stays readable.</p><div class="actions"><button class="button" id="playMotion">Play sequence</button><button class="button secondary" id="pauseMotion">Pause</button></div><p class="meta small-top">800ms scene easing · 420ms explicit flip · 180ms controls. Reduced motion swaps directly. Sequence pauses offscreen or when the tab is hidden.</p></div><div class="motion-stage"><div class="motion-folio" id="motionFolio" data-stage="1"><p class="eyebrow">LIC-17 / Synthetic</p><h3 id="motionTitle">Source folio</h3><hr><div class="receipt-stamp" id="motionStamp">Clause reference §4.3</div></div></div></div><div class="three big-top"><div class="rail"><h3>Section reveal</h3><p class="small-top">A paper aperture can open into the next chapter. Text loads first; native scroll remains available.</p></div><div class="rail"><h3>Controlled pacing</h3><p class="small-top">At most two short pinned chapters on the eventual Home. None below 1024px or on short screens.</p></div><div class="rail"><h3>Readable fallback</h3><p class="small-top">Reduced motion uses complete stills, instant tabs and no parallax. User-selected context always persists.</p></div></div>''','lilac')
html+=section('commercial','15','Scope before scale.','Pricing and statistics use the same evidence discipline as the product. These are proposed commercial and scope specimens.','''<div class="metrics"><div class="metric"><strong>5</strong><p>Proposed modules</p></div><div class="metric"><strong>5</strong><p>Separate use rights</p></div><div class="metric"><strong>1</strong><p>Source family in initial pilot scope</p></div></div><p class="meta">Proposed scope, not customer traction.</p><div class="split big-top"><div class="panel"><p class="eyebrow">One-family pilot / hypothesis</p><h3>Begin with a reviewed matrix.</h3><div class="price">$7,500</div><ul class="checklist"><li>Approved metadata and clause references</li><li>Shadow policy checks</li><li>Ambiguity log and named reviewer</li><li>Rights owner and counsel participation</li></ul><a class="button" href="#forms">Workshop form specimen →</a></div><div class="panel"><p class="eyebrow">Potential ongoing engagement / hypothesis</p><h3>Expand an agreed scope.</h3><div class="price">$2,500<small> / month</small></div><p>Per governed source family. Subject to pilot findings and agreed inclusions.</p><ul class="checklist"><li>Source-family definition: scope to confirm</li><li>Review, support and limits: scope to confirm</li><li>No implied unlimited records or requests</li></ul><p class="meta">Proposed pricing · Not an active offer · No checkout</p></div></div><details class="small-top"><summary>What is included in the price hypothesis?</summary><p class="small-top">Pilot duration, record limits, contracting party, counsel engagement and legal-review costs remain to be agreed. Proof, Signal and Report are proposed directions, not automatically included paid plans.</p></details>''')
html+=section('testimonials','16','A place for future customer voices.','Fictional placeholders for layout exploration. No customer testimonials yet.','''<div class="split"><div class="testimonial"><p class="meta">ILLUSTRATIVE TESTIMONIAL — FICTIONAL PLACEHOLDER</p><blockquote id="quoteText">“The useful question is what this source permits for this specific use.”</blockquote><p id="quoteRole">Example buyer role: Data governance lead</p><div class="actions"><button class="button secondary" id="quotePrev" aria-label="Previous illustrative quote">←</button><button class="button secondary" id="quoteNext" aria-label="Next illustrative quote">→</button><span class="meta" id="quoteCount" aria-live="polite">1 of 3</span></div></div><div>'''+image('rights-folio','Task illustration for an example governance role; not a customer portrait')+'''<p class="meta small-top">Replace individually with approved, attributable feedback. No invented people, customer logos, ratings or claimed outcomes.</p></div></div>''','lilac')
html+=section('forms','17','Complete states, clear next steps.','Sign-in and workshop form specimens are local previews. They collect no credentials, submit nothing and store no form values.','''<div class="split"><div class="form-panel"><p class="eyebrow">Access preview</p><h3>Inspect the synthetic workspace.</h3><p>No account is needed for these fixture examples. Authentication is not connected.</p><a class="button small-top" href="#workbench">Enter synthetic workspace →</a><div class="line big-top"><h3>Form states</h3><p class="small-top">Visible labels, retained input on errors, a consent checkbox and honest completion feedback.</p><span class="pill counsel small-top">No password or SSO collection</span></div></div><form class="form-panel" id="workshopForm" novalidate><p class="eyebrow">Rights-matrix workshop / preview</p><h3>Scope one source family.</h3><div class="form-grid"><div class="field"><label for="email">Work email</label><input id="email" type="email" autocomplete="off" aria-describedby="emailHelp"><small id="emailHelp">Use an example address for this local specimen.</small></div><div class="field"><label for="company">Company</label><input id="company" autocomplete="off"></div><div class="field"><label for="role">Your role</label><select id="role"><option value="">Select role</option><option>Data governance</option><option>Licensing counsel</option><option>Data partnerships</option><option>Retrieval engineer</option></select></div><div class="field"><label for="sourceFamily">Source family / high-level only</label><input id="sourceFamily" placeholder="e.g. licensed reference content" autocomplete="off"></div></div><label class="check"><input id="consent" type="checkbox"><span>For this preview, I acknowledge the privacy explanation below. This is not stored as actual consent.</span></label><p class="meta">No agreements, secrets or logs. Fields remain in page memory only, with no submission, analytics or persistence. Reset clears them. A real form requires operator, retention and deletion details.</p><div class="actions"><button class="button" type="submit">Preview completion →</button><button class="button secondary" type="reset">Reset fields</button></div><p class="small-top" id="formStatus" role="status"></p></form></div>''','sheet')
html+=section('downloads','18','A kit you can build from.','The documents, assets and specimens travel together. Production implementation and real customer validation remain separate milestones.','''<div class="download-grid"><a href="CONSENT_WAYPOINT_BRAND_IDENTITY.md"><strong>Brand identity ↗</strong><span>Positioning, identity, components and motion rules.</span></a><a href="CONSENT_WAYPOINT_INFORMATION_ARCHITECTURE.md"><strong>Website IA ↗</strong><span>All pages, five modules, pricing, stats and placeholders.</span></a><a href="DESIGN_SYSTEM.md"><strong>Component specification ↗</strong><span>Working interactions and artifact inventory.</span></a><a href="brand-tokens.json" download><strong>Design tokens ↓</strong><span>Semantic implementation source.</span></a><a href="ASSET_PROVENANCE.json"><strong>Asset provenance ↗</strong><span>Original art, font and social sources.</span></a><a href="../Consent-Waypoint-brand-kit.zip" download><strong>Complete kit ↓</strong><span>Portable HTML, CSS, scripts, fonts and assets.</span></a></div>''')
